function normalizeAdzunaItem(raw) {
    return {
      source: 'adzuna.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company ? raw.company.display_name : null,
      url: raw.redirect_url,
      location: raw.location ? raw.location.display_name : null,
      posted_at: raw.created ? raw.created.slice(0, 10) : null,
      raw_extra: {
        description_snippet: raw.description || null,
        salary_min: raw.salary_min || null,
        salary_max: raw.salary_max || null,
        contract_type: raw.contract_type || null,
        contract_time: raw.contract_time || null,
        category: raw.category ? raw.category.label : null,
        description_full: raw.fullDescription || null,
      },
    };
  }

  const input = items[0].json;

  if (!input || !Array.isArray(input.results)) {
    // Échec explicite plutôt qu'avalé silencieusement : une réponse Adzuna
    // de forme inattendue (auth invalide, changement d'API, etc.) doit
    // faire échouer l'exécution n8n, visible dans l'historique et
    // interceptable par un futur Error Workflow — pas juste 0 offre Adzuna
    // ce jour-là sans que personne ne le sache.
    throw new Error('Adzuna: réponse inattendue — ' + JSON.stringify(input));
  }

  return input.results.map(item => ({ json: normalizeAdzunaItem(item) }));

function normalizeJoobleItem(raw) {
    return {
      source: 'jooble.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company || null,
      url: raw.link,
      location: raw.location || null,
      posted_at: raw.updated ? raw.updated.slice(0, 10) : null,
      raw_extra: {
        description_snippet: raw.snippet || null,
        salary: raw.salary || null,
        type: raw.type || null,
        source_name: raw.source || null,
        description_full: raw.fullDescription || null,
      },
    };
  }

  const input = items[0].json;

  if (!input || !Array.isArray(input.jobs)) {
    // Voir le commentaire équivalent dans "Normalize Adzuna" — échec
    // explicite plutôt qu'avalé silencieusement.
    throw new Error('Jooble: réponse inattendue — ' + JSON.stringify(input));
  }

  return input.jobs.map(item => ({ json: normalizeJoobleItem(item) }));

function cleanHtml(s) {
    if (!s) return null;
    return String(s).replace(/<[^>]*>/g, '').trim();
  }

  function normalizeJobRoomItem(raw) {
    const ad = raw.jobAdvertisement;
    const content = ad.jobContent || {};
    const descriptions = content.jobDescriptions || [];
    const desc = descriptions.find(d => d.languageIsoCode === 'fr') || descriptions[0] || {};
    const location = content.location || {};
    return {
      source: 'job-room.ch',
      source_id: ad.id,
      title: cleanHtml(desc.title),
      company: content.company ? content.company.name : null,
      url: content.externalUrl || ('https://www.job-room.ch/job-search/detail/' + ad.id),
      location: [location.city, location.cantonCode].filter(Boolean).join(', ') || null,
      posted_at: ad.createdTime ? ad.createdTime.slice(0, 10) : null,
      raw_extra: {
        description_snippet: cleanHtml(desc.description) || null,
        canton: location.cantonCode || null,
      },
    };
  }

  // n8n éclate automatiquement une réponse HTTP dont le corps est un tableau
  // JSON en un item par élément — chaque items[i].json est donc déjà UNE
  // offre ({ jobAdvertisement: {...}, favouriteItem: null }), jamais le
  // tableau complet. Aucun résultat pour ce mot-clé donne simplement zéro
  // item (pas une erreur).
  if (items.length === 0) return [];

  const malformed = items.find(item => !item.json || !item.json.jobAdvertisement);
  if (malformed) {
    // Échec explicite plutôt qu'avalé silencieusement — voir le commentaire
    // équivalent dans "Normalize Adzuna".
    throw new Error('Job-Room: réponse inattendue — ' + JSON.stringify(malformed.json));
  }

  // Certaines annonces EXTERN (agrégées depuis un autre portail) arrivent
  // avec un champ title corrompu par Job-Room — un fragment de description
  // ("&nbsp;", "*  02 août 2026", "## VOTRE RÔLE ##", "Nous recherchons...")
  // au lieu d'un vrai intitulé de poste. On écarte ces annonces plutôt que de
  // les afficher telles quelles dans le digest.
  function looksLikeGarbageTitle(title) {
    if (!title) return true;
    const t = title.trim();
    if (t.length < 3 || t.length > 140) return true;
    return /^(&nbsp;|[*#,]|nous recherchons|entreprise|afin de|ce poste)/i.test(t);
  }

  return items
    .map(item => normalizeJobRoomItem(item.json))
    .filter(job => !looksLikeGarbageTitle(job.title))
    .map(job => ({ json: job }));

const html = items[0].json.data;
  const pattern = new RegExp('<script type="application/ld\\+json">(.*?)<\\/script>', 's');
  const match = html.match(pattern);
  if (!match) return [];

  const ldJson = JSON.parse(match[1]);
  const itemList = ldJson.find(entry => entry['@type'] === 'ItemList');
  if (!itemList) return [];

  const results = itemList.itemListElement.map(entry => {
    const job = entry.item;
    return {
      json: {
        id: job.identifier ? job.identifier.value : null,
        title: job.title,
        company: job.hiringOrganization ? job.hiringOrganization.name : null,
        url: job.url,
        location: job.jobLocation && job.jobLocation.address ? job.jobLocation.address.addressLocality
  || null : null,
        postedDate: job.datePosted ? job.datePosted.slice(0, 10) : null,
        contractType: job.employmentType || null,
        remote: null,
        description: job.description || null,
      },
    };
  });

  const seen = new Set();
  const deduped = [];
  for (const item of results) {
    const key = String(item.json.title || '').trim().toLowerCase()
      + '|' + String(item.json.company || '').trim().toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    deduped.push(item);
  }

  return deduped;

function normalizeJobchListing(raw) {
    return {
      source: 'jobs.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company,
      url: raw.url,
      location: raw.location,
      posted_at: raw.postedDate || null,
      raw_extra: {
        contract_type: raw.contractType || null,
        remote: raw.remote || null,
        description: raw.description || null,
      },
    };
  }

  return items.map(item => ({ json: normalizeJobchListing(item.json) }));

const FRENCH_WORDS = ['et', 'le', 'la', 'les', 'des', 'pour', 'avec', 'notre', 'nos', 'vous', 'êtes',
  'nous', 'recherchons', 'poste', 'équipe', 'expérience', 'compétences'];
  const GERMAN_WORDS = ['und', 'der', 'die', 'das', 'mit', 'für', 'sind', 'werden', 'sie', 'ihre',
  'unsere', 'kenntnisse', 'erfahrung', 'aufgaben', 'wir', 'suchen', 'stelle', 'unternehmen'];
  const ITALIAN_WORDS = ['e', 'il', 'la', 'di', 'per', 'con', 'sono', 'nostra', 'nostro', 'esperienza',
  'competenze', 'cerchiamo', 'azienda', 'lavoro'];
  const ENGLISH_WORDS = ['the', 'and', 'you', 'our', 'for', 'with', 'are', 'will', 'team', 'looking',
  'join', 'experience', 'skills', 'role', 'we'];

  function buildMarker(words) {
    return new RegExp('\\b(' + words.join('|') + ')\\b', 'gi');
  }

  const FRENCH_MARKERS = buildMarker(FRENCH_WORDS);
  const GERMAN_MARKERS = buildMarker(GERMAN_WORDS);
  const ITALIAN_MARKERS = buildMarker(ITALIAN_WORDS);
  const ENGLISH_MARKERS = buildMarker(ENGLISH_WORDS);

  const LOCATION_ALIASES = {
    'genève': ['genève', 'geneva', 'genf', 'ginevra'],
    'lausanne': ['lausanne', 'losanna'],
    'neuchâtel': ['neuchâtel', 'neuenburg', 'neuchatel'],
  };

  // Offres explicitement hors Suisse romande (canton alémanique/tessinois
  // détecté dans la localisation) : exclusion dure, indépendante du score de
  // pertinence par mot-clé — un poste "data engineer" à Zürich ne doit
  // jamais apparaître, même bien noté par ailleurs. Localisation vide/absente
  // = bénéfice du doute (pas exclu), voir locationIncomplete.
  const NON_ROMANDIE_MARKERS = [
    'zürich', 'zurich', /\bzh\b/, 'winterthur', 'uster', 'dietikon',
    'bern', 'berne', /\bbe\b/, 'thun', 'köniz', 'biel', 'bienne',
    'basel', 'bâle', /\bbs\b/, /\bbl\b/,
    'luzern', 'lucerne', /\blu\b/,
    'zug', /\bzg\b/,
    'aargau', 'argovie', /\bag\b/, 'baden', 'wettingen', 'aarau',
    'schwyz', /\bsz\b/,
    'st. gallen', 'st.gallen', 'saint-gall', /\bsg\b/, 'wil', 'rapperswil',
    'thurgau', 'thurgovie', /\btg\b/, 'frauenfeld',
    'schaffhausen', 'schaffhouse', /\bsh\b/,
    'glarus', 'glaris', /\bgl\b/,
    'graubünden', 'grisons', /\bgr\b/, 'chur', 'coire',
    'appenzell', /\bai\b/, /\bar\b/,
    'solothurn', 'soleure', /\bso\b/,
    'uri', /\bur\b/,
    'obwalden', /\bow\b/,
    'nidwalden', /\bnw\b/,
    'ticino', 'tessin', /\bti\b/, 'lugano', 'bellinzona', 'locarno',
    'valais', 'wallis', /\bvs\b/, 'sion', 'sierre', 'brig', 'brigue',
    // Cantons volontairement hors périmètre (pas alémaniques, mais exclus
    // sur préférence explicite) : Fribourg, Neuchâtel.
    'fribourg', 'freiburg', /\bfr\b/, 'bulle', 'romont',
    'neuchâtel', 'neuchatel', 'neuenburg', /\bne\b/, 'chaux-de-fonds', 'le locle',
  ];

  function isNonRomandieLocation(location) {
    const text = String(location || '').toLowerCase();
    if (!text) return false;
    return NON_ROMANDIE_MARKERS.some((marker) =>
      marker instanceof RegExp ? marker.test(text) : text.includes(marker)
    );
  }

  const EXPANDED_KEYWORDS = ['database engineer', 'data architect', 'analytics engineer', 'data ops',
  'platform engineer', 'site reliability engineer', 'sre', 'cloud engineer', 'infrastructure engineer'];

  const JUNIOR_WORDS = ['junior', 'intern', 'internship', 'graduate', 'entry-level', 'entry level'];

  function searchableText(listing) {
    return [
      listing.title || '',
      listing.raw_extra && (listing.raw_extra.description || listing.raw_extra.description_snippet ||
  listing.raw_extra.description_full) || '',
    ].join(' ').toLowerCase();
  }

  function locationMatches(listing, profile) {
    const location = (listing.location || '').toLowerCase();
    if (!location) return false;
    return profile.locations.some((loc) => {
      const locLower = loc.toLowerCase();
      const aliases = LOCATION_ALIASES[locLower] || [locLower];
      return aliases.some(alias => location.includes(alias));
    });
  }

  function detectForeignLanguage(listing) {
    const text = searchableText(listing);
    const counts = {
      fr: (text.match(FRENCH_MARKERS) || []).length,
      de: (text.match(GERMAN_MARKERS) || []).length,
      it: (text.match(ITALIAN_MARKERS) || []).length,
      en: (text.match(ENGLISH_MARKERS) || []).length,
    };

    const nonFrenchMax = Math.max(counts.de, counts.it, counts.en);

    if (counts.fr >= 2 && counts.fr >= nonFrenchMax) return null;
    if (nonFrenchMax < 2) return null;

    if (counts.de === nonFrenchMax) return 'de';
    if (counts.it === nonFrenchMax) return 'it';
    return 'en';
  }

  function scoreListing(listing, profile) {
    const text = searchableText(listing);
    const titleText = (listing.title || '').toLowerCase();

    // Job-Room et jobup.ch ne filtrent pas fiablement par mot-clé côté API
    // (une recherche "devops" peut renvoyer "Chef de projet technique" ou
    // "Business Analyst" — le mot n'apparaît que quelque part dans la
    // description). Les mots-clés du profil doivent donc matcher le TITRE,
    // pas juste la description, sous peine de faire remonter des postes
    // hors-sujet qui mentionnent la techno en passant. Les mots-clés élargis
    // (EXPANDED_KEYWORDS) restent en texte complet car ce sont déjà des
    // synonymes bonus à faible poids, pas le critère principal.
    const matchedCore = profile.keywords.filter(kw => titleText.includes(kw.toLowerCase()));
    const matchedExpanded = EXPANDED_KEYWORDS.filter(kw => text.includes(kw));

    if (matchedCore.length === 0 && matchedExpanded.length === 0) return 0;

    let score = matchedCore.length * 3 + matchedExpanded.length * 1;

    const isJunior = JUNIOR_WORDS.some(w => new RegExp(`\\b${w}\\b`, 'i').test(text));
    if (isJunior) score += 2;

    if (locationMatches(listing, profile)) score += 1;

    return score;
  }

  const profile = $('Loop Over Items').first().json;

  return items
    .map(item => {
      const score = scoreListing(item.json, profile);
      const text = searchableText(item.json);
      const keywordsMatched = [...profile.keywords, ...EXPANDED_KEYWORDS].filter(kw =>
  text.includes(kw.toLowerCase()));
      const outsideRomandie = isNonRomandieLocation(item.json.location);
      return {
        json: {
          ...item.json,
          matchScore: score,
          matchCategory: outsideRomandie ? 'excluded' : (score >= 3 ? 'primary' : score >= 1 ? 'secondary' : 'excluded'),
          foreignLanguage: detectForeignLanguage(item.json),
          locationIncomplete: !item.json.location,
          keywordsMatched,
          searchProfileId: profile.id,
        },
      };
    })
    .filter(item => item.json.matchCategory !== 'excluded')
    .sort((a, b) => b.json.matchScore - a.json.matchScore);

const original = $('Filter by profile').item.json;
  const translations = $json.translations || [];

  return {
    json: {
      ...original,
      title: translations[0] ? translations[0].text : original.title,
      raw_extra: {
        ...original.raw_extra,
        description_fr: translations[1] ? translations[1].text : null,
        title_original: original.title,
      },
    },
  };

