        postedDate: job.datePosted ? job.datePosted.slice(0, 10) : null,
        contractType: job.employmentType || null,
        remote: null,
        description: job.description || null,
      },
    };
  });

  const seen = new Set();
  const deduped = [];
  for (const item of results) {
    const key = String(item.json.title || '').trim().toLowerCase()
      + '|' + String(item.json.company || '').trim().toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    deduped.push(item);
  }

  return deduped;

function normalizeJobupListing(raw) {
    return {
      source: 'jobup.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company,
      url: raw.url,
      location: raw.location,
      posted_at: raw.postedDate || null,
      raw_extra: {
        contract_type: raw.contractType || null,
        remote: raw.remote || null,
        description: raw.description || null,
      },
    };
  }

  return items.map(item => ({ json: normalizeJobupListing(item.json) }));

// Dédoublonnage inter-jours : même garde-fou que pour jobs.ch, par
// précaution — jobup.ch partage l'infrastructure JobCloud avec jobs.ch et
// pourrait avoir le même comportement de réattribution d'ID à la
// republication d'une offre déjà vue les jours précédents.
const recent = $('Recent jobup.ch listings').all().map(i => i.json);
const seen = new Set(recent.map(r => (r.title || '') + '|' + (r.company || '')));

const incoming = $('Normalize jobup.ch').all();
return incoming.filter(item => {
  const key = String(item.json.title || '').trim().toLowerCase()
    + '|' + String(item.json.company || '').trim().toLowerCase();
  return !seen.has(key);
});
